  Lemma x_memset : forall (Q : machine_state -> Prop) R1 F fc m XSc sk LBk RT SF FT HT (retpc : Z),
    rfull R1 -> rtbl Wx R1 RT -> ftbl Wx (xS1 e) m SF -> ftbl Wx ff m FT -> ftbl Wx (ff / 8) m HT -> Px XSc sk LBk m -> mem_inv asegs m ->
    PropExec.getr R1 10 = Z_to_bv 64 (ff + 32) -> PropExec.getr R1 11 = Z_to_bv 64 0 -> PropExec.getr R1 12 = Z_to_bv 64 16 ->
    PropExec.getr R1 2 = Z_to_bv 64 (xS1 e) -> PropExec.getr R1 1 = Z_to_bv 64 retpc ->
    0 <= retpc < 2 ^ 64 -> retpc mod 2 = 0 ->
    forallb (fun j => fent_in (SHBASE + 4 + Z.of_nat j, 1%nat, ELit 0) HT) (seq 0 2) = true ->
    fin 0 24 (fkeys SF) = true -> fin 0 2040 (fkeys FT) = true -> fin SHBASE (SHBASE + 256) (fkeys HT) = true ->
    (forall R2 m2, rfull R2 -> rtbl Wx R2 (LbA_DCtorK.keptf RT) -> ftbl Wx (xS1 e) m2 SF ->
       ftbl Wx ff m2 (fdrop 32 16 FT ++ zents 32 2) -> ftbl Wx (ff / 8) m2 HT -> Px XSc sk LBk m2 -> mem_inv asegs m2 ->
       evt asegs Q (MS R2 F (Z_to_bv 64 retpc) fc None m2 (seg_rom asegs))) ->
